example:
composition "Map" { ample 1  tempo 100  master-seed 78 }

midi-clip phrase {
  chords C Am F G
  bars 4
}

synth source {
  wave triangle
  gain -9 dB
  from phrase.notes -> notes
}

curve slow {
  value auto(1:0, 5:1000)
}

map open {
  unit Hz
  out_low 300
  out_high 4500
  smooth 400 ms
  from slow.level -> input
}

filter sweep {
  type lowpass
  from source.audio -> audio
  from open.level -> cutoff
}

master output {
  from sweep.audio -> audio
}
